def getmodbuscrc16(data: bytes) -> bytes:
    """计算 Modbus CRC16 校验码，并以小端两字节返回
    多数 Modbus RTU 帧末尾附加此两字节 CRC (低字节在前)。
    """
    crc = 0xFFFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if (crc & 0x0001) != 0:
                crc >>= 1
                crc ^= 0xA001
            else:
                crc >>= 1
    return crc.to_bytes(2, 'little')

