def topo_sort_kahn(n: int, adj: list[list[int]]) -> list[int]:
    indeg = [0]*n
    for u in range(n):
        for v in adj[u]:
            indeg[v] += 1
    q = deque([i for i in range(n) if indeg[i] == 0])
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return order

def kmp_search(text: str, pat: str) -> list[int]:
    n, m = len(text), len(pat)
    if m == 0:
        return []
    lps = [0]*m
    j = 0
    for i in range(1, m):
        while j and pat[i] != pat[j]:
            j = lps[j-1]
        if pat[i] == pat[j]:
            j += 1
            lps[i] = j
    res = []
    j = 0
    for i in range(n):
        while j and text[i] != pat[j]:
            j = lps[j-1]
        if text[i] == pat[j]:
            j += 1
            if j == m:
                res.append(i - m + 1)
                j = lps[j-1]
    return res

def rabin_karp(text: str, pat: str) -> list[int]:
    n, m = len(text), len(pat)
    if m == 0 or m > n:
        return []
    B, MOD = 131, 1_000_000_007
    powB = pow(B, m-1, MOD) if m > 1 else 1
    hpat = 0
    hwin = 0
    for i in range(m):
        hpat = (hpat*B + ord(pat[i])) % MOD
        hwin = (hwin*B + ord(text[i])) % MOD
    out = []
    for i in range(n-m+1):
        if hpat == hwin and text[i:i+m] == pat:
            out.append(i)
        if i < n - m:
            hwin = (hwin - ord(text[i])*powB) % MOD
            hwin = (hwin*B + ord(text[i+m])) % MOD
    return out

def sieve_is_prime(n: int) -> list[int]:
    is_prime = [1]*(n+1)
    if n >= 0: is_prime[0] = 0
    if n >= 1: is_prime[1] = 0
    p = 2
    while p*p <= n:
        if is_prime[p]:
            step = p
            start = p*p
            for x in range(start, n+1, step):
                is_prime[x] = 0
        p += 1
    return is_prime

