def quickselect(a: list[int], k: int) -> int:
    # k is 1-based
    k -= 1
    l, r = 0, len(a) - 1
    while l <= r:
        pivot = a[r]
        i = l
        for j in range(l, r):
            if a[j] <= pivot:
                a[i], a[j] = a[j], a[i]
                i += 1
        a[i], a[r] = a[r], a[i]
        if i == k:
            return a[i]
        elif i > k:
            r = i - 1
        else:
            l = i + 1
    raise IndexError('k out of range')

