def min_window(s: str, t: str) -> str:
    if not t:
        return ''
    need = Counter(t)
    need_cnt = len(t)
    l = 0
    res = ''
    for r, ch in enumerate(s):
        if ch in need:
            if need[ch] > 0:
                need_cnt -= 1
            need[ch] -= 1
        while need_cnt == 0:
            cand = s[l:r+1]
            if not res or len(cand) < len(res):
                res = cand
            ch2 = s[l]
            if ch2 in need:
                need[ch2] += 1
                if need[ch2] > 0:
                    need_cnt += 1
            l += 1
    return res

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []
    intervals = sorted([i[:] for i in intervals])
    res = [intervals[0][:]]
    for a,b in intervals[1:]:
        la, lb = res[-1]
        if a <= lb:
            res[-1][1] = max(lb, b)
        else:
            res.append([a,b])
    return res

class TrieNode:
