def shell_sort(a):
    n = len(a)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            tmp = a[i]
            j = i
            while j >= gap and a[j-gap] > tmp:
                a[j] = a[j-gap]
                j -= gap
            a[j] = tmp
        gap //= 2
    return a

def heap_sort(a):
    n = len(a)
    def heapify(a, n, i):
        largest = i
        l, r = 2*i+1, 2*i+2
        if l < n and a[l] > a[largest]: largest = l
        if r < n and a[r] > a[largest]: largest = r
        if largest != i:
            a[i], a[largest] = a[largest], a[i]
            heapify(a, n, largest)
    for i in range(n//2-1, -1, -1): heapify(a, n, i)
    for i in range(n-1, 0, -1):
        a[0], a[i] = a[i], a[0]
        heapify(a, i, 0)
    return a

