    pos = 0
    while pos <= n - m:
        j = 0
        while j < m and text[pos+j] == pattern[j]: j += 1
        if j == m: return pos
        if pos + m < n: pos += shift.get(text[pos+m], m + 1)
        else: return -1
    return -1

from threading import Lock
from collections import OrderedDict

class ThreadSafeLRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.lock = Lock()

    def get(self, key):
        with self.lock:
            if key not in self.cache: return None
            self.cache.move_to_end(key)
            return self.cache[key]

    def put(self, key, value):
        with self.lock:
            if key in self.cache: self.cache.move_to_end(key)
            self.cache[key] = value
            if len(self.cache) > self.capacity:
                self.cache.popitem(last=False)

import queue, threading

def producer_consumer(producer, consumer, count, buf_size=10):
    q = queue.Queue(buf_size)
    results = []
    def run_producer():
        for i in range(count): q.put(producer(i))
        q.put(None)
    def run_consumer():
        nonlocal results
        while True:
            item = q.get()
            if item is None:
                q.put(None)
                break
            results.append(consumer(item))
    t1 = threading.Thread(target=run_producer)
    t2 = threading.Thread(target=run_consumer)
    t1.start(); t2.start()
    t1.join(); t2.join()
    return results

import hashlib

class BloomFilter:
    def __init__(self, size):
        self.size = size
        self.bits = [False] * size

    def _h1(self, s): return int(hashlib.md5(s.encode()).hexdigest(), 16) % self.size
    def _h2(self, s): return int(hashlib.sha1(s.encode()).hexdigest(), 16) % self.size

    def add(self, s):
        self.bits[self._h1(s)] = True
        self.bits[self._h2(s)] = True

    def contains(self, s):
        return self.bits[self._h1(s)] and self.bits[self._h2(s)]

import random

class SkipListNode:
    def __init__(self, key, value, level):
        self.key, self.value, self.forward = key, value, [None]*(level+1)

class SkipList:
    def __init__(self, max_level=16):
        self.max_level = max_level
        self.head = SkipListNode(-1, None, max_level)
        self.level = 0

    def _random_level(self):
        lvl = 1
        while random.random() < 0.5 and lvl < self.max_level: lvl += 1
        return lvl

    def insert(self, key, value):
        update = [self.head] * (self.max_level+1)
        curr = self.head
        for i in range(self.level, -1, -1):
            while curr.forward[i] and curr.forward[i].key < key: curr = curr.forward[i]
            update[i] = curr
        lvl = self._random_level()
        if lvl > self.level: self.level = lvl
        new_node = SkipListNode(key, value, lvl)
        for i in range(lvl+1):
            new_node.forward[i] = update[i].forward[i]
            update[i].forward[i] = new_node

    def search(self, key):
        curr = self.head
        for i in range(self.level, -1, -1):
            while curr.forward[i] and curr.forward[i].key < key: curr = curr.forward[i]
        curr = curr.forward[0]
        if curr and curr.key == key: return curr.value
        return None

